import { STORAGE_PREFIX } from '@proton/shared/lib/authentication/persistedSessionStorage';

import { LAST_ACTIVE_PING } from '../store/_user/useActivePing';
import { sendErrorReport } from './errorHandling';
import { getLastActivePersistedUserSessionUID, getLastPersistedLocalID } from './lastActivePersistedUserSession';

jest.mock('./errorHandling');
const mockedSendErrorReport = jest.mocked(sendErrorReport);

describe('getLastActivePersistedUserSessionUID', () => {
    afterEach(() => {
        window.localStorage.clear();
    });

    it('returns UID if valid session data exists', () => {
        localStorage.setItem(`${LAST_ACTIVE_PING}-1234`, JSON.stringify({ value: Date.now() }));
        localStorage.setItem(`${STORAGE_PREFIX}session`, JSON.stringify({ UserID: '1234', UID: 'abcd-1234' }));

        const result = getLastActivePersistedUserSessionUID();
        expect(result).toBe('abcd-1234');
    });

    it('returns null when there are no active sessions', () => {
        const result = getLastActivePersistedUserSessionUID();
        expect(result).toBeNull();
    });

    it('returns last active session for any apps if there is no sessions for Drive', () => {
        localStorage.setItem(
            `${STORAGE_PREFIX}0`,
            JSON.stringify({ UserID: '1234', UID: 'abcd-1234', persistedAt: 123 })
        );
        localStorage.setItem(
            `${STORAGE_PREFIX}1`,
            JSON.stringify({ UserID: '5678', UID: 'abcd-5678', persistedAt: 567 })
        );
        localStorage.setItem(
            `${STORAGE_PREFIX}2`,
            JSON.stringify({ UserID: '9999', UID: 'abcd-9999', persistedAt: 345 })
        );
        const result = getLastActivePersistedUserSessionUID();
        expect(result).toBe('abcd-5678');
    });

    it('handles JSON parse errors', () => {
        localStorage.setItem(`${LAST_ACTIVE_PING}-1234`, 'not a JSON');
        const result = getLastActivePersistedUserSessionUID();
        expect(result).toBeNull();
        expect(mockedSendErrorReport).toHaveBeenCalled();
    });

    // This test is a security to break the build if the constants changes since business logic rely on both these constants thru our code base
    it('assert constants', () => {
        expect(LAST_ACTIVE_PING).toEqual('drive-last-active');
        expect(STORAGE_PREFIX).toEqual('ps-');
    });
});

describe('getLastPersistedLocalID', () => {
    beforeEach(() => {
        localStorage.clear();
        jest.clearAllMocks();
    });

    test('returns 0 when localStorage is empty', () => {
        expect(getLastPersistedLocalID()).toBe(0);
    });

    test('returns the correct ID for a single item', () => {
        localStorage.setItem(`${STORAGE_PREFIX}123`, JSON.stringify({ persistedAt: Date.now() }));
        expect(getLastPersistedLocalID()).toBe(123);
    });

    test('returns the highest ID when multiple items exist', () => {
        localStorage.setItem(`${STORAGE_PREFIX}123`, JSON.stringify({ persistedAt: Date.now() - 1000 }));
        localStorage.setItem(`${STORAGE_PREFIX}456`, JSON.stringify({ persistedAt: Date.now() }));
        localStorage.setItem(`${STORAGE_PREFIX}789`, JSON.stringify({ persistedAt: Date.now() - 2000 }));
        expect(getLastPersistedLocalID()).toBe(456);
    });

    test('ignores non-prefixed keys', () => {
        localStorage.setItem(`${STORAGE_PREFIX}123`, JSON.stringify({ persistedAt: Date.now() }));
        localStorage.setItem('otherKey', JSON.stringify({ persistedAt: Date.now() + 1000 }));
        expect(getLastPersistedLocalID()).toBe(123);
    });

    test('handles non-numeric IDs correctly', () => {
        localStorage.setItem(`${STORAGE_PREFIX}abc`, JSON.stringify({ persistedAt: Date.now() }));
        expect(getLastPersistedLocalID()).toBe(0);
    });

    it('returns correct ID if valid session data exists from last ping', () => {
        localStorage.setItem(`${LAST_ACTIVE_PING}-1234`, JSON.stringify({ value: Date.now() }));
        localStorage.setItem(`${STORAGE_PREFIX}4`, JSON.stringify({ UserID: '1234', UID: 'abcd-1234' }));
        expect(getLastPersistedLocalID()).toBe(4);
    });
});

import type { PersistedSession } from '@proton/shared/lib/authentication/SessionInterface';
import { STORAGE_PREFIX } from '@proton/shared/lib/authentication/persistedSessionStorage';

import { LAST_ACTIVE_PING } from '../store/_user/useActivePing';
import { sendErrorReport } from './errorHandling';
import { EnrichedError } from './errorHandling/EnrichedError';

const getLastActiveUserId = () => {
    const storageKeys = Object.keys(localStorage);
    let lastActiveUserId = '';
    let lastAccess = 0;

    for (const k of storageKeys) {
        if (k.startsWith(LAST_ACTIVE_PING)) {
            const data = JSON.parse(localStorage[k]);
            const lastPing = Number(data.value);
            if (lastAccess < lastPing) {
                lastAccess = lastPing;
                lastActiveUserId = k.substring(k.indexOf(LAST_ACTIVE_PING) + LAST_ACTIVE_PING.length + 1);
            }
        }
    }
    return lastActiveUserId || null;
};

export const getLastPersistedLocalID = (): number => {
    try {
        const storageKeys = Object.keys(localStorage);
        // Get localID from last active session
        // This support multi tabs and multi accounts
        const lastActiveUserId = getLastActiveUserId();
        if (lastActiveUserId) {
            for (const k of storageKeys) {
                if (k.startsWith(STORAGE_PREFIX)) {
                    const data = JSON.parse(localStorage[k]);
                    if (data.UserID === lastActiveUserId && data.UID) {
                        return Number(k.substring(STORAGE_PREFIX.length));
                    }
                }
            }
        }

        // Fallback: rely on last storage prefix
        // This does not support multi tabs
        let lastLocalID: { ID: number; persistedAt: number } | null = null;
        for (const k of storageKeys) {
            if (k.startsWith(STORAGE_PREFIX)) {
                const data = JSON.parse(localStorage[k]) as { persistedAt: number };
                if (lastLocalID === null || data.persistedAt > lastLocalID.persistedAt) {
                    lastLocalID = {
                        persistedAt: data.persistedAt,
                        ID: Number(k.substring(STORAGE_PREFIX.length)),
                    };
                }
            }
        }

        return lastLocalID?.ID || 0;
    } catch (e) {
        sendErrorReport(
            new EnrichedError('Failed to parse JSON from localStorage', {
                extra: {
                    e,
                },
            })
        );
        return 0;
    }
};

export const getLastActivePersistedUserSessionUID = (): string | null => {
    try {
        // Last Active Persisted Session in Drive apps
        const storageKeys = Object.keys(localStorage);
        const lastActiveUserId = getLastActiveUserId();
        if (lastActiveUserId) {
            for (const k of storageKeys) {
                if (k.startsWith(STORAGE_PREFIX)) {
                    const data = JSON.parse(localStorage[k]);
                    if (data.UserID === lastActiveUserId && data.UID) {
                        return data.UID;
                    }
                }
            }
        }

        // Last Active Persisted Session in any apps
        let persistedSession: PersistedSession | null = null;
        for (const k of storageKeys) {
            if (k.startsWith(STORAGE_PREFIX)) {
                const data = JSON.parse(localStorage[k]) as PersistedSession;
                if (persistedSession === null || data.persistedAt > persistedSession.persistedAt) {
                    persistedSession = data;
                }
            }
        }

        return persistedSession?.UID ?? null;
    } catch (e) {
        sendErrorReport(
            new EnrichedError('Failed to parse JSON from localStorage', {
                extra: {
                    e,
                },
            })
        );
        return null;
    }
};

import { stringToUtf8Array } from '@proton/crypto/lib/utils';
import isTruthy from '@proton/utils/isTruthy';
import noop from '@proton/utils/noop';

import { removeLastRefreshDate } from '../api/helpers/refreshStorage';
import createListeners from '../helpers/listeners';
import { getItem, removeItem, setItem } from '../helpers/storage';
import type {
    DefaultPersistedSession,
    OfflinePersistedSession,
    PersistedSession,
    PersistedSessionBlob,
    PersistedSessionWithLocalID,
} from './SessionInterface';
import { InvalidPersistentSessionError } from './error';
import { getValidatedLocalID } from './fork/validation';
import type { OfflineKey } from './offlineKey';
import { getDecryptedBlob, getEncryptedBlob } from './sessionBlobCryptoHelper';

// We have business logic relying on this constant, please change with caution!
export const STORAGE_PREFIX = 'ps-';
const getKey = (localID: number) => `${STORAGE_PREFIX}${localID}`;

const sessionRemovalListeners = createListeners<PersistedSession[], Promise<void>>();

export const registerSessionRemovalListener = (listener: (persistedSessions: PersistedSession) => Promise<void>) => {
    sessionRemovalListeners.subscribe(listener);
};

export const getPersistedSession = (localID: number): PersistedSession | undefined => {
    const itemValue = getItem(getKey(localID));
    if (!itemValue) {
        return;
    }
    try {
        const parsedValue = JSON.parse(itemValue);
        return {
            UserID: parsedValue.UserID || '',
            UID: parsedValue.UID || '',
            blob: parsedValue.blob || '',
            isSubUser: parsedValue.isSubUser || false,
            persistent: typeof parsedValue.persistent === 'boolean' ? parsedValue.persistent : true, // Default to true (old behavior)
            trusted: parsedValue.trusted || false,
            payloadVersion: parsedValue.payloadVersion || 1,
            persistedAt: parsedValue.persistedAt || 0,
            ...(parsedValue.offlineKeySalt
                ? {
                      payloadType: 'offline',
                      offlineKeySalt: parsedValue.offlineKeySalt,
                  }
                : { payloadType: 'default' }),
        };
    } catch (e: any) {
        return undefined;
    }
};

export const removePersistedSession = async (localID: number, UID: string) => {
    const oldSession = getPersistedSession(localID);
    if (oldSession?.UID) {
        removeLastRefreshDate(oldSession.UID);
    }
    if (!oldSession || (oldSession.UID && UID !== oldSession.UID)) {
        return;
    }
    if (sessionRemovalListeners.length()) {
        await Promise.all(sessionRemovalListeners.notify(oldSession)).catch(noop);
    }
    removeItem(getKey(localID));
};

export const getPersistedSessions = (): PersistedSessionWithLocalID[] => {
    const localStorageKeys = Object.keys(localStorage);
    return localStorageKeys
        .filter((key) => key.startsWith(STORAGE_PREFIX))
        .map((key) => {
            const localID = getValidatedLocalID(key.slice(STORAGE_PREFIX.length));
            if (localID === undefined) {
                return;
            }
            const result = getPersistedSession(localID);
            if (!result) {
                return;
            }
            return {
                ...result,
                localID,
            };
        })
        .filter(isTruthy);
};

export const getPersistedSessionBlob = (blob: string): PersistedSessionBlob | undefined => {
    try {
        const parsedValue = JSON.parse(blob);
        const keyPassword = parsedValue.keyPassword || '';
        const offlineKeyPassword = parsedValue.offlineKeyPassword || '';

        if (parsedValue.offlineKeyPassword) {
            return {
                type: 'offline',
                keyPassword,
                offlineKeyPassword,
            };
        }

        return {
            type: 'default',
            keyPassword,
        };
    } catch (e: any) {
        return undefined;
    }
};

export const getDecryptedPersistedSessionBlob = async (
    key: CryptoKey,
    blob: string,
    payloadVersion: PersistedSession['payloadVersion']
): Promise<PersistedSessionBlob> => {
    const decryptedBlob = await getDecryptedBlob(
        key,
        blob,
        payloadVersion === 2 ? stringToUtf8Array('session') : undefined
    ).catch(() => {
        throw new InvalidPersistentSessionError('Failed to decrypt persisted blob');
    });
    const parsedBlob = getPersistedSessionBlob(decryptedBlob);
    if (!parsedBlob) {
        throw new InvalidPersistentSessionError('Failed to parse persisted blob');
    }
    return parsedBlob;
};

export const setPersistedSessionWithBlob = async (
    localID: number,
    key: CryptoKey,
    data: {
        UserID: string;
        UID: string;
        keyPassword: string;
        offlineKey: OfflineKey | undefined;
        isSubUser: boolean;
        persistent: boolean;
        trusted: boolean;
    }
) => {
    const payloadVersion =
        1 as PersistedSession['payloadVersion']; /* Update to 2 when all clients understand it (safe for rollback) */

    const { clearTextPayloadData, encryptedPayloadData } = ((): {
        clearTextPayloadData:
            | Pick<OfflinePersistedSession, 'payloadType' | 'offlineKeySalt'>
            | Pick<DefaultPersistedSession, 'payloadType'>;
        encryptedPayloadData: PersistedSessionBlob;
    } => {
        if (data.offlineKey) {
            return {
                clearTextPayloadData: {
                    payloadType: 'offline',
                    offlineKeySalt: data.offlineKey.salt,
                },
                encryptedPayloadData: {
                    keyPassword: data.keyPassword,
                    offlineKeyPassword: data.offlineKey.password,
                },
            } as const;
        }

        return {
            clearTextPayloadData: {
                payloadType: 'default',
            },
            encryptedPayloadData: {
                keyPassword: data.keyPassword,
            },
        } as const;
    })();

    const persistedSession: PersistedSession = {
        UserID: data.UserID,
        UID: data.UID,
        isSubUser: data.isSubUser,
        persistent: data.persistent,
        trusted: data.trusted,
        payloadVersion,
        ...clearTextPayloadData,
        blob: await getEncryptedBlob(
            key,
            JSON.stringify(encryptedPayloadData),
            payloadVersion === 2 ? stringToUtf8Array('session') : undefined
        ),
        persistedAt: Date.now(),
    };
    setItem(getKey(localID), JSON.stringify(persistedSession));
};

import { useEffect, useMemo, useState } from 'react';

import { useApi, useAuthentication } from '@proton/components/hooks';
import useLoading from '@proton/hooks/useLoading';
import { resumeSession } from '@proton/shared/lib/authentication/persistedSessionHelper';

import usePublicToken from '../../hooks/drive/usePublicToken';
import { getLastPersistedLocalID } from '../../utils/lastActivePersistedUserSession';
import { usePublicSession } from '../_api';
import { useDriveShareURLBookmarkingFeatureFlag } from '../_bookmarks';
import { useBookmarks } from '../_bookmarks/useBookmarks';
import { usePublicShare } from '../_shares';

export const useBookmarksPublicView = (customPassword?: string) => {
    const { user, isUserLoading } = usePublicShare();
    const { getSessionInfo } = usePublicSession();
    const { listBookmarks, addBookmark } = useBookmarks();
    const [bookmarksTokens, setBookmarksTokens] = useState<Set<string>>(new Set());
    const [isLoading, withLoading, setIsLoading] = useLoading(true);
    const isDriveShareUrlBookmarkingEnabled = useDriveShareURLBookmarkingFeatureFlag();
    const api = useApi();
    const { token, urlPassword } = usePublicToken();
    const auth = useAuthentication();

    useEffect(() => {
        if (!user || !isDriveShareUrlBookmarkingEnabled) {
            if (!isUserLoading) {
                setIsLoading(false);
            }
            return;
        }
        const UID = getSessionInfo()?.sessionUid;
        if (!UID) {
            return;
        }
        const abortControler = new AbortController();
        void withLoading(async () => {
            // TODO: We need to find a better way of doing this
            (api as any).UID = UID;

            const resumedSession = await resumeSession({ api, localID: getLastPersistedLocalID() });
            if (resumedSession.keyPassword) {
                auth.setPassword(resumedSession.keyPassword);
            }

            const bookmarks = await listBookmarks(abortControler.signal);
            setBookmarksTokens(new Set(bookmarks.map((bookmark) => bookmark.token.Token)));
        });
        return () => {
            abortControler.abort();
        };
    }, [user, isUserLoading, isDriveShareUrlBookmarkingEnabled]);

    const isAlreadyBookmarked = useMemo(() => {
        return bookmarksTokens.has(token);
    }, [bookmarksTokens, token]);

    const handleAddBookmark = async () => {
        const abortSignal = new AbortController().signal;
        await addBookmark(abortSignal, { token, urlPassword: urlPassword + customPassword });
        setBookmarksTokens((prevState) => new Set([...prevState, token]));
    };

    return {
        urlPassword,
        isLoading,
        isLoggedIn: !!user,
        addBookmark: handleAddBookmark,
        isAlreadyBookmarked,
    };
};

import type { APP_NAMES } from '../../constants';
import { APPS, APPS_CONFIGURATION } from '../../constants';
import { validateEmailAddress } from '../../helpers/email';
import { decodeBase64URL, stringToUint8Array } from '../../helpers/encoding';
import { ExtraSessionForkSearchParameters, ForkSearchParameters, ForkType, ForkableApps } from './constants';

export const getValidatedApp = (app = ''): APP_NAMES | undefined => {
    if (ForkableApps.has(app as any)) {
        return app as APP_NAMES;
    }
    if (
        app.startsWith('proton-') &&
        app.match(/-/g)?.length === 1 &&
        /^[a-z-]+$/.test(app) &&
        app.length >= 10 &&
        app.length < 16
    ) {
        const protonAppName = app as APP_NAMES;
        if (APPS_CONFIGURATION[protonAppName]) {
            return;
        }
        const safeAppName = app.replace('proton-', '');
        APPS_CONFIGURATION[protonAppName] = Object.entries(APPS_CONFIGURATION[APPS.PROTONMAIL]).reduce(
            (acc, [key, value]) => {
                acc[key as keyof typeof acc] = value.replace('mail', safeAppName).replace('Mail', 'Account (internal)');
                return acc;
            },
            APPS_CONFIGURATION[APPS.PROTONMAIL]
        );
        return app as APP_NAMES;
    }
};

export const getValidatedLocalID = (localID = '') => {
    if (!localID) {
        return;
    }
    const maybeLocalID = parseInt(localID, 10);
    if (Number.isInteger(maybeLocalID) && maybeLocalID >= 0 && maybeLocalID <= 100000000) {
        return maybeLocalID;
    }
};

export const getLocalIDForkSearchParameter = (searchParams: URLSearchParams) => {
    const localID = searchParams.get(ForkSearchParameters.LocalID) || '';
    return getValidatedLocalID(localID);
};

export const getValidatedRawKey = (str: string) => {
    try {
        return stringToUint8Array(decodeBase64URL(str));
    } catch (e: any) {
        return undefined;
    }
};
export const getValidatedForkType = (str: string) => {
    if (Object.values(ForkType).includes(str as ForkType)) {
        return str as ForkType;
    }
};

export const getEmailSessionForkSearchParameter = (searchParams: URLSearchParams) => {
    const email = searchParams.get(ExtraSessionForkSearchParameters.Email) || '';
    if (validateEmailAddress(email)) {
        return email.toLowerCase();
    }
};

